  .input-row { display: flex; gap: 10px; margin-bottom: 20px; }
  .input-row input { flex: 1; padding: 12px 16px; border: 2px solid #ddd; border-radius: 8px; font-size: 1rem; outline: none; transition: border-color 0.2s; }
